#!/usr/bin/env python3
"""One-off: regenerate tools/kani/run shim from the spec (root-side)."""
import os, re

spec = open("/src/portable/builders/tools/kani.sh", encoding="utf-8").read()
m = re.search(r"ft::make_shim '(.*?)'\n", spec, re.S)
body = m.group(1)
shim = (
    "#!/bin/sh\n"
    "# generated by formal-tools portable builders - do not edit\n"
    'FT_ROOT=$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd)\n'
    'TOOL_DIR="$FT_ROOT/tools/kani"\n'
    + body + "\n"
)
open("/k/run", "w", encoding="utf-8").write(shim)
os.chmod("/k/run", 0o755)
print("PATCHED bytes=", len(shim))
